"""Discover read-only calibration inputs without fixing the UI to two payloads.

The public dataset paths identify one payload directory each. A user can pass a
parent directory to ``scan``; its children are discovered and paired by name.
Only the small catalog under runs is written, never the selected inputs.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
from pathlib import Path

RAW_FOLDERS = ("Temp_Vbias", "X", "X_new", "source", "tb_data", "x_data", "src_data")


def validate_payload(value: str) -> str:
    value = str(value).strip()
    if (
        not value
        or len(value) > 80
        or value in (".", "..")
        or any(character in value for character in '<>:"/\\|?*')
        or any(ord(character) < 32 for character in value)
        or value.endswith((".", " "))
        or re.fullmatch(r"(?i)(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\..*)?", value)
    ):
        raise ValueError("载荷编号须为 1–80 个字符，不能包含路径分隔符或系统保留文件名")
    return value


def _key(value: str) -> str:
    normalized = re.sub(r"[^a-z0-9]", "", str(value).lower())
    return {
        "02": "14b",
        "grid02": "14b",
        "grid14b": "14b",
        "03": "15b",
        "grid03": "15b",
        "grid15b": "15b",
        "grid10brawdata": "10b",
    }.get(normalized, normalized)


def _label(path: Path) -> str:
    return {"10b": "10B", "14b": "14B", "15b": "15B"}.get(_key(path.name), path.name)


class DatasetCatalog:
    def __init__(self, workspace: Path):
        self.workspace = Path(workspace).resolve()
        self.path = self.workspace / "runs" / "datasets.json"

    def saved(self) -> dict | None:
        """Read saved choices without probing removable or network input roots."""
        try:
            value = json.loads(self.path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return None
        if not isinstance(value, dict) or not isinstance(value.get("datasets"), list):
            return None
        if not isinstance(value.get("defaults"), dict):
            return None
        return value

    def _path(self, value, *, required=False):
        if value is None or not str(value).strip():
            if required:
                raise ValueError("未选择目录")
            return None
        path = Path(os.path.expandvars(str(value).strip())).expanduser()
        if not path.is_absolute():
            path = self.workspace / path
        path = path.resolve()
        if not path.is_dir():
            raise ValueError(f"目录不存在或不是文件夹: {path}")
        return path

    @staticmethod
    def _is_raw(path):
        return any((path / name).is_dir() for name in RAW_FOLDERS)

    @staticmethod
    def _is_product(path):
        return (path / "tb").is_dir() or (path / "ec").is_dir()

    def _raw_sources(self, path):
        if path is None:
            return []
        if path.name in RAW_FOLDERS and self._is_raw(path.parent):
            return [path.parent]
        if self._is_raw(path):
            return [path]
        return sorted(
            (child for child in path.iterdir() if child.is_dir() and self._is_raw(child)),
            key=lambda p: p.name,
        )

    def _product_sources(self, path):
        if path is None:
            return []
        if self._is_product(path):
            return [path]
        # A previously saved run can be selected directly, as can its products/.
        if (path / "products").is_dir():
            return self._product_sources(path / "products")
        return sorted(
            (child for child in path.iterdir() if child.is_dir() and self._is_product(child)),
            key=lambda p: p.name,
        )

    def defaults(self):
        raw = self.workspace / "14、15B标定数据"
        if not raw.is_dir():
            raw = next(
                (
                    child
                    for child in sorted(self.workspace.iterdir())
                    if child.is_dir() and self._raw_sources(child)
                ),
                raw,
            )
        products = self.workspace / "products"
        return {
            "raw_dir": str(raw) if raw.is_dir() else None,
            "product_dir": str(products) if products.is_dir() else None,
        }

    def resolve(self, dataset: dict) -> dict:
        """Return a normalized, validated payload definition for a saved run."""
        if not isinstance(dataset, dict):
            raise ValueError("数据集定义须为对象")
        raw = self._path(dataset.get("raw_dir"))
        product = self._path(dataset.get("product_dir"))
        source_name = str(dataset.get("source_payload") or dataset.get("payload") or "")
        raw_candidates = self._raw_sources(raw)
        product_candidates = self._product_sources(product)
        if raw and not raw_candidates:
            # Explicitly selected future layouts are configured in the reading
            # profile; discovery need not assume today's subdirectory names.
            pass
        elif raw and len(raw_candidates) != 1:
            matches = [item for item in raw_candidates if _key(item.name) == _key(source_name)]
            if len(matches) != 1:
                raise ValueError(
                    "原始数据目录含多个载荷或未发现 Temp_Vbias/X/X_new/source，请选择其中一个载荷目录"
                )
            raw = matches[0]
        elif raw_candidates:
            raw = raw_candidates[0]
        if product and len(product_candidates) != 1:
            matches = [item for item in product_candidates if _key(item.name) == _key(source_name)]
            if len(matches) != 1:
                raise ValueError("产品目录含多个载荷或未发现 tb/ec，请选择其中一个载荷目录")
            product = matches[0]
        elif product_candidates:
            product = product_candidates[0]
        if raw is None and product is None:
            raise ValueError("至少需要选择原始数据目录或产品目录")
        payload = validate_payload(dataset.get("payload") or _label(raw or product))
        source_payload = product.name if product else str(dataset.get("source_payload") or payload)
        profile = dataset.get("profile")
        if profile not in ("10B", "14B", "15B"):
            profile = next(
                (
                    {"10b": "10B", "14b": "14B", "15b": "15B"}[_key(value)]
                    for value in ((raw.name if raw else ""), source_payload, payload)
                    if _key(value) in ("10b", "14b", "15b")
                ),
                None,
            )
        record = {
            "payload": payload,
            "label": payload,
            "raw_dir": str(raw) if raw else None,
            "product_dir": str(product) if product else None,
            "source_payload": source_payload,
            "profile": profile,
        }
        # Preset selection follows the directory the user explicitly selected;
        # an automatically paired default directory must not override it.
        roles = dataset.get("selection_roles")
        if roles is not None:
            if (
                not isinstance(roles, list)
                or not roles
                or any(role not in ("raw", "product") for role in roles)
            ):
                raise ValueError("目录选择来源无效")
            record["selection_roles"] = sorted(set(roles))
        identity = json.dumps(record, sort_keys=True, ensure_ascii=False).encode("utf-8")
        return {"id": hashlib.sha256(identity).hexdigest()[:16], **record}

"""Workbench adapters for the library's seven scientific processors.

The workbench stores revisions and provenance separately from the wiki-defined
scientific files. Historical products are read-only inputs; processors write only
inside a workspace run. No peak or surface fitting algorithm is implemented here.
"""

from __future__ import annotations

import copy
import json
import math
import re
import shutil
from dataclasses import replace
from pathlib import Path
from typing import Any

import matplotlib

matplotlib.use("Agg")

import numpy as np
from lmfit.models import ExponentialModel, GaussianModel, LinearModel, QuadraticModel

from ..common.spectral_models import detector_identity, photopeak_channels, unsupported_spectral_model
from ..common.utils import (
    DataLayout,
    read_json,
    read_parquet_metadata,
    validated_events,
    write_json,
)
from ..config.payload_config import (
    EC_PROCESS_PARAMS,
    TB_PROCESS_PARAMS,
    PayloadConfig,
    SourceSpec,
    get_payload_config,
)
from ..ec.processors.L0_processor import ECL0Processor
from ..ec.processors.L1_processor import ECL1Processor
from ..ec.processors.L2_processor import ECL2Processor
from ..ec.processors.L3_processor import ECL3Processor
from ..tb.processors.L0_processor import TBL0Processor
from ..tb.processors.L1_processor import TBL1Processor
from ..tb.processors.L2_processor import TBL2Processor
from .acquisition import discover, tb_histogram_config, validate_profile
from .datasets import DatasetCatalog, validate_payload
from .dependencies import tb_package

LAYERS = ("TB_L0", "TB_L1", "TB_L2", "EC_L0", "EC_L1", "EC_L2", "EC_L3")


def _stem(value: str) -> str:
    return str(value).removesuffix(".parquet").removesuffix("_corr.l1").removesuffix(".l0")


def _clean(value: Any) -> Any:
    """JSON has no NaN/Infinity: missing numerical diagnostics become null."""
    if isinstance(value, dict):
        return {str(key): _clean(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, np.ndarray)):
        return [_clean(item) for item in value]
    if isinstance(value, (np.floating, float)):
        return float(value) if math.isfinite(value) else None
    if isinstance(value, np.integer):
        return int(value)
    if isinstance(value, Path):
        return str(value)
    return value


class ComputeAdapter:
    def __init__(self, workspace: Path, dataset: dict | None = None, acquisition: dict | None = None,
                 *, response_payload: str | None = None):
        self.workspace = Path(workspace).resolve()
        self.dataset = DatasetCatalog(self.workspace).resolve(dataset) if dataset is not None else None
        self.source_payload = self.dataset["source_payload"] if self.dataset else None
        self.history = (
            Path(self.dataset["product_dir"]).parent
            if self.dataset and self.dataset.get("product_dir")
            else self.workspace / "products"
        )
        self.resources = Path(__file__).resolve().parents[1] / "resources"
        self.acquisition = validate_profile(acquisition) if acquisition is not None else None
        self.response_payload = response_payload

    def detector_payload(self, payload):
        return self.response_payload or detector_identity(payload, self.dataset)

    def unavailable_reason(self, layer):
        capabilities = (self.acquisition or {}).get("processing_capabilities", {})
        capability = capabilities.get(layer, {}) if isinstance(capabilities, dict) else {}
        if isinstance(capability, dict) and capability.get("supported") is False:
            reason = capability.get("reason")
            return (
                reason.strip()
                if isinstance(reason, str) and reason.strip()
                else f"当前读取预设不支持 {layer}"
            )
        return None

    def observations(self, payload):
        return discover(self._base_config(payload)[1], self.acquisition) if self.acquisition else None

    def historical_layer(self, payload: str, layer: str) -> Path:
        """Read-only source layer; an edited output label never renames its input."""
        if self.dataset:
            if self.dataset.get("product_dir"):
                kind, level = layer.split("_")
                return Path(self.dataset["product_dir"]) / kind.lower() / level
            # A raw-only dataset must not silently inherit an unrelated default.
            return self.workspace / "runs" / "_no_historical_products" / payload / layer
        return self._layer_dir(self.history, payload, layer)

    @staticmethod
    def _source_config(raw: Path):
        """Infer known isotope metadata from filenames, keeping fitting in lib."""
        directory = raw / "source"
        peaks = {}
        for label in ("14B", "15B"):
            for spec in get_payload_config(label).source_specs:
                peaks[spec.name.lower()] = (spec.name, list(spec.peak_energies_keV))
        specs, background, issues = [], {}, []
        for event in sorted(directory.glob("*.event.dat")):
            prefix = re.split(r"[_-]", event.name, maxsplit=1)[0].lower()
            if prefix not in peaks and prefix not in ("bkg", "background"):
                issues.append(f"不能从源文件 {event.name} 识别能线；请提供 Na22/Cs137/Co60 名称或显式源规格")
                continue
            exposure = re.search(r"(?:_|-)(\d+)\s*([mh])(?:_|-)", event.name, re.I)
            if not exposure:
                issues.append(f"源文件 {event.name} 缺少曝光时间；请用 _5m_ / _1h_ 命名并配置曝光时间")
                continue
            minutes = int(exposure.group(1)) * (60 if exposure.group(2).lower() == "h" else 1)

            def signature(name):
                stem = re.sub(r"(?:[_-]ecu)?[_-]\d+\.(?:event\.dat|hk)$", "", name, flags=re.I)
                return re.sub(r"[^a-z0-9]", "", stem.lower())

            matching = [
                path for path in directory.glob("*.hk") if signature(path.name) == signature(event.name)
            ]
            if len(matching) != 1:
                issues.append(f"源文件 {event.name} 未能唯一匹配 hk 文件")
                continue
            if prefix in ("bkg", "background"):
                background = {
                    "bkg_event_file": event.name,
                    "bkg_hk_file": matching[0].name,
                    "bkg_exposure_minutes": minutes,
                }
            else:
                name, energies = peaks[prefix]
                specs.append(SourceSpec(name, event.name, matching[0].name, minutes, energies))
        return specs, background, issues

    def _base_config(self, payload: str):
        validate_payload(payload)
        profile = self.dataset.get("profile") if self.dataset else payload
        try:
            cfg = get_payload_config(profile)
        except ValueError:
            cfg = PayloadConfig(payload, payload, Path("."), Path("."), Path("."), Path("."))
        raw = (
            Path(self.dataset["raw_dir"])
            if self.dataset and self.dataset.get("raw_dir")
            else self.workspace / "runs" / "_no_raw_data"
            if self.dataset
            else self.workspace / "14、15B标定数据" / cfg.payload_id
        ):
            raise ValueError("Invalid run ID")
        root = self.runs / run_id
        if not (root / "state.json").is_file():
            raise FileNotFoundError("试算不存在")
        return root

    def read(self, run_id):
        with self.lock:
            return json.loads((self.root(run_id) / "state.json").read_text(encoding="utf-8"))

    def save(self, state):
        with self.lock:
            write(self.root(state["id"]) / "state.json", state)

    def inventory(self, payload):
        if payload not in ("14B", "15B"):
            raise ValueError("payload 必须为 14B 或 15B")
        if payload not in self.inventory_cache:
            self.inventory_cache[payload] = self.adapter.inventory(payload)
        return copy.deepcopy(self.inventory_cache[payload])

    def adapter_for(self, state):
        if state.get("acquisition"):
            return ComputeAdapter(self.workspace, state.get("dataset"), load_profile(state["acquisition"]),
                                  response_payload=_response_payload(state))
        return ComputeAdapter(self.workspace, state["dataset"], response_payload=_response_payload(state)) if state.get("dataset") else self.adapter

    def acquisition_defaults(self, profile=None):
        return {"profile": prepare_profile(self.workspace, payload_profile=profile), "presets": presets()}

    def acquisition(self, run_id):
        state = self.read(run_id)
        reference = state.get("acquisition")
        profile = (
            load_profile(reference)
            if reference
            else prepare_profile(
                self.workspace,
                payload_profile=(state.get("dataset") or {}).get("profile") or state["payload"],
            )
        )
        profile = {key: value for key, value in profile.items() if not key.startswith("_")}
        return {
            "profile": profile,
            "revision": reference["revision"] if reference else 0,
            "sha256": reference["sha256"] if reference else profile_digest(profile),
            "presets": presets(),
            "acquisition_preset": state.get("acquisition_preset"),
        }

    def preview_acquisition(self, run_id, profile):
        state = self.read(run_id)
        prepared = prepare_profile(self.workspace, profile)
        adapter = ComputeAdapter(self.workspace, state.get("dataset"), prepared)
        raw_root = adapter._base_config(state["payload"])[1]
        result = adapter.observations(state["payload"])
        if not raw_root.is_dir():
            result["errors"] = []
        result["sha256"] = profile_digest(prepared)
        result["warnings"] = (
            [] if result["rows"] else ["当前未发现原始数据；可保存规则，计算前需载入匹配文件。"]
        )
        return result

    def save_acquisition(self, run_id, profile, reason=None, *, preset_reference=None):
        with self.lock:
            state = self.read(run_id)
            if any(job["status"] in ("queued", "running") for job in state["jobs"]):
