+.quality-table { border-collapse: collapse; width: 100%; font-size: 12px; text-align: left; font-variant-numeric: tabular-nums; }
+.quality-table th { position: sticky; top: 0; z-index: 1; background: #f6f8fa; color: var(--secondary); font-weight: 500; white-space: nowrap; }
+.quality-table th, .quality-table td { padding: 8px 10px; border-bottom: 1px solid var(--line-light); }
+.quality-table tr[aria-selected="true"] td { background: var(--blue-tint); }
+.quality-table button { font-size: 12px; padding: 2px 0; text-align: left; white-space: nowrap; }
+.quality-table td:nth-child(4) { white-space: nowrap; }
+#tb-analysis[data-layer="TB_L1"] { scroll-margin-top: 72px; }
+#l1-back-to-quality { font-size: 12px; padding: 3px 0; }
+@media (max-width: 700px) {
+  .quality-controls { width: 100%; gap: 8px; }
+  .quality-controls label { flex: 1; flex-wrap: wrap; }
+  .quality-controls select { width: 100%; }
+  .l1-quality-chart { height: 300px; }
+  .quality-counts { gap: 6px; }
+  .quality-heading h3 { font-size: 14px; }
+}

